        const n = x.length / 8;
        for (let i = 0; i < n; i++) {
            for (let j = 0; j < 8; j++) {
                y[j] ^= plaintext[i * 8 + j];
            }
            y = this._cipher.enc8(y);
            x.set(y, i * 8);
        }
        return x;
    }
}

