// Hooks noVNC up to the encrypted tunnel, served by tabtopd (see e2e.go).
// The image's noVNC asks window.tabtopChannel for a channel to use instead
// of its WebSocket URL: a TunnelSocket carrying RFB. The tunnel's login is
// the desktop's: it shows the login form when there's no session, and
// Xvnc, which only the gateway can reach, asks for nothing more.
//
// It also adds buttons to noVNC's control bar that open the terminal and
// the files page, and log out (see nav.js), and uploads files and folders
// dropped on the page into ~/Downloads, as the files page does (see
// drop.js), showing how they go in a transfers panel styled by
// desktop.css. While the desktop is connected, when a file is saved into
// ~/Downloads, as when the desktop's browser finishes downloading one, a
// notice offers to download it here (see watchDownloads), and text copied
// on either side reaches the other's clipboard (see shareClipboard). Ten
// minutes before the login runs out, a banner offers to log in again (see
// expiry.js).

import { glyphs, iconDataURL } from "./glyphs.js";
import { TunnelSocket } from "./tunnel.js";
import { logOut, nameTab, openPage, terminalOn, pages } from "./nav.js";
import { dropUploads } from "./drop.js";
import { call, folderInfo, loadRoots, makeFolder, setLoginTitle, uploadFile, uploadNote } from "./requests.js";
import { fetchFile } from "./download.js";
import { humanBytes } from "./file-format.js";
import { warnExpiry } from "./expiry.js";

window.tabtopChannel = () => new TunnelSocket({ type: "vnc" }, { title: "Desktop" });

nameTab("desktop");
warnExpiry();

// White, as noVNC's own icons are.
const icon = (id) => iconDataURL(id);

const buttons = [
    ["terminal", "Terminal (opens in its own tab)", icon("terminal"), () => openPage("terminal")],
    ["files", "Files in Downloads (opens in its own tab)", icon("files"), () => openPage("files")],
    ["logout", "Log out (here, in the terminal and on the files page)", icon("logout"), logOut],
];

const settings = document.getElementById("noVNC_settings_button");
if (settings) {
    for (const [id, title, src, onClick] of buttons) {
        if (id !== "logout" && !pages.some((page) => page.id === id)) continue;
        const b = Object.assign(document.createElement("input"), { type: "image", id: `tabtop_${id}_button`, className: "noVNC_button", src, alt: title, title });
        b.addEventListener("click", onClick);
        // Log out goes just above Disconnect, with the other ways to leave.
        const disconnect = id === "logout" && document.getElementById("noVNC_disconnect_button");
        if (disconnect) {
            disconnect.before(b);
        } else {
            settings.before(b);
        }
        if (id === "terminal") {
            terminalOn().then((on) => b.classList.toggle("noVNC_hidden", !on));
        }
    }
} else {
    console.warn("tabtop: noVNC's control bar wasn't found; no links to the terminal and files");
}

document.head.append(Object.assign(document.createElement("link"), { rel: "stylesheet", href: new URL("./desktop.css", import.meta.url).href }));
setLoginTitle("Desktop");
if (pages.some((page) => page.id === "files")) {
    dropUploads(uploadFile, makeFolder, () => {}, () => "", () => uploadNote(), folderInfo);
}

// The notices, newest at the top, at most MAX_NOTICES; each stays until
// it's used or dismissed.
const MAX_NOTICES = 4;
const notices = Object.assign(document.createElement("div"), { id: "tabtop_notices" });
notices.setAttribute("role", "status");
document.body.append(notices);

function notice(name, bytes) {
    const button = (text, className, onClick) => {
        const b = Object.assign(document.createElement("button"), { type: "button", textContent: text, className });
        b.addEventListener("click", onClick);
        return b;
    };
    const text = Object.assign(document.createElement("p"), { textContent: `${name} was saved in Downloads (${humanBytes(bytes)}).` });
    const box = document.createElement("div");
    box.className = "notice";
    box.append(text,
        button("Download", "primary", () => {
            box.remove();
            fetchFile(name);
        }),
        button("Files", "", () => openPage("files", "#/")),  // where it is, not the folder last shown
        button(glyphs.close, "close", () => box.remove()));
    box.lastChild.title = box.lastChild.ariaLabel = "Dismiss";
    notices.prepend(box);
    while (notices.children.length > MAX_NOTICES) {
        notices.lastChild.remove();
    }
}

// The watch is only open while the desktop is connected, as the sound is,
// so a tab left disconnected holds nothing open, and the session can end
// for being idle (see session.go).
let wanted = false;    // whether the desktop is connected
let running = false;   // whether watchDownloads is
let watching = null;   // the watch's tunnel, while it's open

// watchDownloads keeps a watch request open while wanted, which the
// server answers with each file saved into ~/Downloads, trying again,
// less often each time, if it's lost; it stops if the server refuses it.
async function watchDownloads() {
    if (running || !pages.some((page) => page.id === "files")) {
        return;
    }
    running = true;
    for (let wait = 2000; wanted; wait = Math.min(wait * 2, 60000)) {
        try {
            const t = await call({ type: "watch" });
            if (!wanted) {
                t.close();
                break;
            }
            watching = t;
            wait = 2000;
            loadRoots(); // logged in now: where drops go can be said
            for (let m; (m = await t.next());) {
                const saved = m.text && JSON.parse(m.text);
                if (saved?.saved) {
                    notice(saved.saved, saved.bytes);
                }
            }
        } catch (err) {
            if (!err.lost) {
                console.warn(`tabtop: no notices of new downloads: ${err.message}`);
                // Refused (Downloads not exposed where the desktop saves,
                // say), not unreachable: where drops go can still be said.
                loadRoots();
                break;
            }
        }
        watching = null;
        if (wanted) {
            await new Promise((r) => setTimeout(r, wait));
        }
    }
    watching = null;
    running = false;
}

// The clipboard -----------------------------------------------------------

// shareClipboard links the desktop's clipboard to this computer's, which
// browsers only allow on HTTPS or localhost. Text copied on the desktop is
// put on this computer's clipboard as it arrives, which the page says, with
// how it starts (see copied): with VNC_ADDR, the desktop is another
// machine, and whatever it copies shouldn't land on this one unnoticed. Text copied here goes to
// the desktop when the page is switched back to, where the browser lets
// the page read the clipboard: Chrome and Edge ask once, the first time
// the desktop is clicked; others, which would ask every time, are left to
// noVNC's clipboard panel. Either way, the panel shows the desktop's.
let shared = null;      // the RFB connection it's set up on
let lastText = null;    // the text last passed either way, not passed back

async function shareClipboard() {
    if (!window.isSecureContext || !navigator.clipboard) {
        return;
    }
    // noVNC's own module, already loaded by the page, and its connection.
    const { default: UI } = await import("../app/ui.js");
    const rfb = UI.rfb;
    if (!rfb || rfb === shared) {
        return;
    }
    shared = rfb;
    rfb.addEventListener("clipboard", (e) => {
        lastText = e.detail.text;
        navigator.clipboard.writeText(e.detail.text).then(() => copied(e.detail.text), () => {
            // Not focused, or not allowed: the panel has it.
        });
    });
}

// copied says, for a few seconds, that the desktop copied text to this
// computer's clipboard, showing how it starts.
const copiedNote = Object.assign(document.createElement("div"), { id: "tabtop_copied", hidden: true });
copiedNote.setAttribute("role", "status");
document.body.append(copiedNote);
let copiedTimer = 0;
function copied(text) {
    const line = text.replace(/[\x00-\x1f\x7f]+/g, " ").trim();
    const start = line.length > 80 ? `${line.slice(0, 80)}…` : line;
    copiedNote.textContent = `The desktop copied ${text.length} character${text.length === 1 ? "" : "s"} to your clipboard`
        + (start ? `: “${start}”` : ".");
    copiedNote.hidden = false;
    clearTimeout(copiedTimer);
    copiedTimer = setTimeout(() => (copiedNote.hidden = true), 5000);
}

// readable resolves to whether the page may read the clipboard without
// asking ("granted"), may ask ("prompt"), or neither.
async function readable() {
    try {
        return (await navigator.permissions.query({ name: "clipboard-read" })).state;
    } catch {
        return "denied";  // a browser without the permission, as Firefox
    }
}

// sendClipboard passes this computer's clipboard to the desktop, if it's
// changed. With ask, it may ask for permission first.
async function sendClipboard(ask = false) {
    if (!wanted || !shared || !window.isSecureContext || !navigator.clipboard?.readText) {
        return;
    }
    const state = await readable();
    if (state !== "granted" && !(ask && state === "prompt")) {
        return;
    }
    let text;
    try {
        text = await navigator.clipboard.readText();
    } catch {
        return;  // refused, or the page isn't focused
    }
    if (text && text !== lastText) {
        lastText = text;
        shared.clipboardPasteFrom(text);
        const panel = document.getElementById("noVNC_clipboard_text");
        if (panel) {
            panel.value = text;
        }
    }
}

addEventListener("focus", () => sendClipboard());
document.addEventListener("visibilitychange", () => document.visibilityState === "visible" && sendClipboard());
let asked = false;
document.addEventListener("pointerdown", (e) => {
    if (!asked && wanted && e.target.closest?.("#noVNC_container")) {
        asked = true;
        sendClipboard(true);
    }
}, true);

new MutationObserver(() => {
    const connected = document.documentElement.classList.contains("noVNC_connected");
    if (connected !== wanted) {
        wanted = connected;
        connected ? watchDownloads() : watching?.close();
        if (connected) {
            shareClipboard().then(() => sendClipboard());
        }
    }
}).observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

files.tabtop/reconnect.js:
// Trying again once the connection to the server is lost, for the
// terminal and the files page, served by tabtopd. (noVNC does the same for
// the desktop, with its own "Reconnecting...": see entrypoint.sh.) A
// banner at the top says so and counts down to the next try, with a
// button to try at once. Tries come a second apart at first, then further
// apart, up to half a minute, and at once when the browser comes back
// online or the tab is shown again.

const delays = [1, 2, 4, 8, 15, 30];  // seconds before each try; the last repeats

let current = null;
let finish = null;  // ends the one going, as connected

// reconnect shows the banner, saying message, and calls attempt() after
// each wait until it resolves to true, then removes the banner. attempt
// resolving to false, or throwing, means it's still lost. While one is
// going, other calls join it; it resolves once connected again.
export function reconnect(message, attempt) {
    current ??= keepTrying(message, attempt).finally(() => (current = null));
    return current;
}

// reconnected ends the tries, if any are going, since the page has
// reached the server some other way.
export function reconnected() {
    finish?.();
}

function keepTrying(message, attempt) {
    return new Promise((resolve) => {
        const text = document.createElement("span");
        const now = Object.assign(document.createElement("button"), { type: "button", textContent: "Try now" });
        Object.assign(now.style, { font: "inherit", marginLeft: ".75rem" });
        const box = document.createElement("div");
        box.id = "tabtop_reconnect";
        box.setAttribute("role", "status");
        // Just below the bar of links at the top, while it's in view, so
        // the banner doesn't cover them; above the page, below the login
        // form.
        const bar = document.querySelector(".tabtop-nav")?.getBoundingClientRect().bottom ?? 0;
        Object.assign(box.style, {
            position: "fixed", top: `${Math.max(bar, 0) + 8}px`, left: "50%", transform: "translateX(-50%)", zIndex: "999",
            maxWidth: "calc(100vw - 2rem)", boxSizing: "border-box", padding: ".5rem 1rem", borderRadius: "8px",
            font: "14px/1.5 system-ui, sans-serif", color: "#e8e8ea", background: "#5c1d1a",
            boxShadow: "0 2px 12px rgba(0,0,0,.4)",
        });
        box.append(text, now);
        document.body.append(box);

        let tries = 0;
        let timer = 0;
        let tick = 0;
        let trying = false;
        let over = false;
        const go = async () => {
            if (trying || over) {
                return;
            }
            clearTimeout(timer);
            clearInterval(tick);
            trying = true;
            now.disabled = true;
            text.textContent = `${message} Reconnecting…`;
            let ok = false;
            try {
                ok = await attempt();
            } catch {
                // Still lost.
            }
            trying = false;
            now.disabled = false;
            if (!over) {
                ok ? done() : wait();
            }
        };
        const wait = () => {
            const at = Date.now() + delays[Math.min(tries++, delays.length - 1)] * 1000;
            const count = () => {
                text.textContent = `${message} Trying again in ${Math.max(1, Math.ceil((at - Date.now()) / 1000))} s.`;
            };
            count();
            tick = setInterval(count, 1000);
            timer = setTimeout(go, at - Date.now());
        };
        const shown = () => document.visibilityState === "visible" && go();
        const done = () => {
            over = true;
            finish = null;
            clearTimeout(timer);
            clearInterval(tick);
            removeEventListener("online", go);
            document.removeEventListener("visibilitychange", shown);
            box.remove();
            resolve();
        };
        finish = done;
        now.addEventListener("click", go);
        addEventListener("online", go);
        document.addEventListener("visibilitychange", shown);
        wait();
    });
}

files.tabtop/requests.js:
// Requests about ~/Downloads through the encrypted tunnel, served by
// tabtopd (see e2e.go), for the files page and for files dropped on the
// desktop: running one with the session, uploading a file, making a
// folder, and collecting a file or zip that's fetched.

import * as tunnel from "./tunnel.js";
import { filesystemRoot, filesystemRoots, ensureFilesystemRoots, assertWritableRoot, onFilesPage, rootPath, uploadRoot, setUploadRoot, uploadRootPath } from "./fs-context.js";

// The login form's title, if one is needed: the page's name.
let title = "Sign in to TabTop";

export function setLoginTitle(t) {
    title = t;
}

// call runs a request with the session, logging in again if it's over.
// Aborting signal before the reply ends it (see Tunnel.open).
// Its root is req.root, or the page's: on the files page, the one it
// shows; elsewhere none, which the server takes as Downloads at its default
// place (and refuses if that isn't exposed).
export async function call(req, { signal } = {}) {
    const id = req.root ?? (onFilesPage() ? filesystemRoot().id : "");
    const target = id === filesystemRoot().id ? filesystemRoot() : filesystemRoots().find(root => root.id === id);
    req = { ...req, root: id, root_version: req.root_version ?? (id ? target?.version : undefined) };
    for (;;) {
        const session = await tunnel.session(title);
        try {
            return await tunnel.Tunnel.open(req, session, undefined, { signal });
        } catch (err) {
            if (!err.login) {
                throw err;
            }
            tunnel.forgetSession(session);
        }
    }
}

// Uploads are sent in chunks the size of the server's, at most
// UPLOAD_WINDOW of them ahead of those it has acknowledged writing, so a
// slow server or disk doesn't pile the file up in the browser.
const UPLOAD_CHUNK = 256 * 1024;
const UPLOAD_WINDOW = 16;

// Uploads cut off, by File, as {id, dir}: the server keeps
// what it had of one whose connection was lost (see keepPartial in
// upload.go), so uploading the same file into the same folder again, as
// Retry does, carries on from there.
const partial = new WeakMap();

// Waits before each try to carry on with an upload whose connection was
// lost, in seconds (the last repeats), and how long it may go without
// getting anywhere before it fails: well inside the hour the server keeps
// what it had (partialKeep in upload_manager.go).
const RESUME_DELAYS = [1, 2, 4, 8, 15, 30];
const RESUME_GIVE_UP = 15 * 60 * 1000;

// uploadFile uploads a dropped or picked file into the folder dir, and
// returns the name it was saved as, and any warning. With replace, a file
// with its name there is replaced; otherwise it gets a free name. Aborting
// signal ends it, telling the server to delete what it had of the file. If
// it stopped any other way the last time this file was uploaded into dir,
// it carries on from there. (If the file has changed on disk since it was
// picked, the browser won't read it, so it fails rather than mixing the
// two.)
//
// If the connection is lost, it tries again by itself, carrying on from
// what the server has, until it gets somewhere or RESUME_GIVE_UP passes
// without it; meanwhile progress gets the bytes sent and a note saying so.
// Anything else the server says, such as a full disk, fails it at once.
//
// With expect, {mtime, size}, as the file request told of the file it
// replaces, it's only saved if that file is still so (for the editor in
// preview.js): else it fails, saying why. It resolves with the saved
// file's mtime and size too.
export async function uploadFile(file, progress, dir, signal, replace = false,
    { delays = RESUME_DELAYS, giveUp = RESUME_GIVE_UP, expect = null } = {}) {
    const root = await ensureUploadRoot();
    let got = 0;
    let since = Date.now();
    const sent = (bytes) => {
        if (bytes > got) {
            since = Date.now();  // getting somewhere
        }
        got = bytes;
        progress(bytes);
    };
    for (let tries = 0; ; tries++) {
        try {
            return await uploadOnce(file, sent, root, dir, signal, replace, expect);
        } catch (err) {
            if (!err.lost || signal.aborted || Date.now() - since >= giveUp) {
                throw err;
            }
        }
        progress(got, "connection lost, reconnecting…");
        await sleep(delays[Math.min(tries, delays.length - 1)] * 1000, signal);
    }
}

// sleep waits ms, or throws once signal is aborted.
function sleep(ms, signal) {
    return new Promise((resolve, reject) => {
        const done = () => {
            clearTimeout(timer);
            reject(signal.reason);
        };
        const timer = setTimeout(() => {
            signal.removeEventListener("abort", done);
            resolve();
        }, ms);
        signal.addEventListener("abort", done, { once: true });
        if (signal.aborted) {
            done();
        }
    });
}

async function uploadOnce(file, progress, root, dir, signal, replace, expect) {
    signal.throwIfAborted();
    const kept = partial.get(file);
    const resume = kept?.dir === dir ? kept.id : "";
    const t = await call({ type: "upload", root, path: dir, name: file.name, size: file.size,
        ...(replace ? { replace: true } : {}), ...(resume ? { resume } : {}),
        ...(expect ? { if_mtime: expect.mtime, if_size: expect.size } : {}) });
    const abort = () => {
        partial.delete(file);
        try {
            t.sendText(JSON.stringify({ cancel: true }));
        } catch {
            // Lost already: the server keeps it a while, then deletes it.
        }
        t.close();
    };
    signal.addEventListener("abort", abort);
    try {
        signal.throwIfAborted();  // while it was opening
        if (t.reply.id) {
            partial.set(file, { id: t.reply.id, dir });
        }
        const offset = t.reply.offset ?? 0;
        const chunks = Math.ceil((file.size - offset) / UPLOAD_CHUNK);
        let sent = 0;
        let acked = 0;
        progress(offset);
        for (;;) {
            while (sent < chunks && sent - acked < UPLOAD_WINDOW) {
                const start = offset + sent * UPLOAD_CHUNK;
                t.sendData(new Uint8Array(await file.slice(start, start + UPLOAD_CHUNK).arrayBuffer()));
                sent++;
            }
            const m = await t.next();
            if (!m) {
                throw new tunnel.TunnelError(t.closeReason || "connection lost", t.closeLogin, !t.closeReason && !t.closeLogin);
            }
            if (m.text !== undefined) {
                const res = JSON.parse(m.text);
                if (res.name && acked === chunks) {
                    partial.delete(file);
                    return { name: res.name, warning: res.warning, mtime: res.mtime, size: res.size };
                }
                throw new Error(res.error || "the server's reply is malformed");
            }
            acked++;
            progress(Math.min(offset + acked * UPLOAD_CHUNK, file.size));
        }
    } finally {
        signal.removeEventListener("abort", abort);
        t.close();
    }
}

// The site's root, under any base path, which links are made from: this
// script's own address, not one the gateway would have to guess from
// behind a proxy.
const siteRoot = new URL("../", import.meta.url);

// shareURL is the address of the share link with token: to name (as a
// .zip, for a folder, dir), or for uploading, with upload.
export function shareURL(token, { name, dir = false, upload = false }) {
    return new URL(`fs/${token}/${upload ? "" : encodeURIComponent(dir ? name + ".zip" : name)}`, siteRoot).href;
}

// shellPath is the path of path, in the root at root (the page's, by
// default), as a shell takes it: quoted if it needs to be.
export function shellPath(path, root = rootPath()) {
    // The home folder as "~", not "~/."; and nothing after the root for
    // its own top folder.
    root = root.replace(/\/\.$/, "").replace(/(.)\/$/, "$1");
    const quote = value => /^[\w@%+=:,./-]+$/.test(value) ? value : `'${value.replaceAll("'", "'\\''")}'`;
    const join = (a, b) => b ? (a === "/" ? "/" + b : a + "/" + b) : a;
    if (root === "~") return path ? "~/" + quote(path) : "~";
    if (root.startsWith("~/")) return "~/" + quote(join(root.slice(2), path));
    return quote(join(root, path));
}

// loadRoots learns, in the background, the roots exposed, so a page away
// from the files page can say where dropped files will go before any are
// (see uploadRootLabel). It needs the session the page already has.
export function loadRoots() {
    ensureFilesystemRoots(call).catch(() => {});
}

// uploadShellPath is shellPath for path in the root uploads go into.
export function uploadShellPath(path) {
    return shellPath(path, uploadRootPath() ?? rootPath());
}

// uploadNote is "(where uploads go)", followed by more, for the note a
// page away from the files page shows as files are dragged over it.
export function uploadNote(more = "") {
    const where = uploadRootPath();
    return [where ? `(${where})` : "", more].filter(Boolean).join(", ");
}

// ensureUploadRoot resolves to the id of the root uploads go into, once
// it's known to be one that can be written to: the files page's own, or
// elsewhere uploadRoot (see fs-context.js): the Downloads the server has
// at its default place, where the browser saves, if it can be written to;
// else one asked for, once. The page's root stays as it was: the desktop
// still watches, and fetches its new downloads from, Downloads.
async function ensureUploadRoot() {
    await ensureFilesystemRoots(call);
    if (onFilesPage()) {
        assertWritableRoot();
        return filesystemRoot().id;
    }
    if (!uploadRoot()) {
        const writable = filesystemRoots().filter(root => !root.read_only);
        const downloads = writable.find(root => root.default);
        if (downloads) setUploadRoot(downloads);
        else {
            if (!writable.length) throw new Error("No writable filesystem root is exposed.");
            // Asked once, however many uploads start meanwhile: they all
            // wait for the one answer. Cancelled, it's asked again next time.
            choosing ??= (async () => {
                const { askChoice } = await import("./ui.js");
                const id = await askChoice("Upload into which folder?", writable.map(root => [root.id, root.label]));
                if (id !== null) setUploadRoot(writable.find(root => root.id === id));
                return id;
            })().finally(() => { choosing = null; });
            if ((await choosing) === null) throw new Error("Upload cancelled.");
        }
    }
    return uploadRoot().id;
}
let choosing = null;

// folderInfo resolves, for uploads into the folder dir, to {names, free}:
// the names of the files in it (not its folders, which an upload can't
// replace), and the bytes free there, or null if the server can't tell.
export async function folderInfo(dir) {
    const root = await ensureUploadRoot();
    const t = await call({ type: "list", root, path: dir });
    t.close();
    return { names: new Set(t.reply.entries.filter((e) => !e.dir).map((e) => e.name)), free: t.reply.free ?? null };
}

// makeFolder makes the folder name in dir for an upload, and returns the
// name it got.
export async function makeFolder(dir, name) {
    const root = await ensureUploadRoot();
    const t = await call({ type: "mkdir", root, path: dir, name });
    t.close();
    return t.reply.name;
}

// createFile makes an empty file name in dir, and returns the name it got.
export async function createFile(dir, name) {
    const root = await ensureUploadRoot();
    const t = await call({ type: "create", root, path: dir, name });
    t.close();
    return t.reply.name;
}

// complete reports whether a download that's ended came whole: all size
// bytes of a file, or a zip (size null) the server said it finished.
export function complete(t, got, size) {
    return size === null ? t.trailer?.done === true : got === size;
}

// collect gathers the rest of a file or zip request t into a Blob of
// type, calling progress(bytes) as it goes, and throws if it ends before
// all size bytes (see complete) have come. Each chunk becomes a Blob as it
// arrives, which moves it out of the page's memory into the browser's blob
// storage; Chrome keeps large ones in temporary files on disk.
export async function collect(t, size, progress, type = "application/octet-stream") {
    const chunks = [];
    let got = 0;
    for (let data; (data = await t.nextChunk());) {
        if (size !== null && got + data.byteLength > size) {
            t.close();
            throw new Error("more than the file's size");
        }
        chunks.push(new Blob([data]));
        got += data.byteLength;
        progress(got);
    }
    if (!complete(t, got, size)) {
        throw new Error(t.closeReason || "connection lost");
    }
    return new Blob(chunks, { type });
}

// SERVER_DECODED are the types of pictures most browsers can't show, which
// tabtopd decodes for them (see heif.go): HEIC and HEIF. (AVIF, they show.)
export const SERVER_DECODED = new Set(["image/heic", "image/heif"]);

// serverDecoded resolves to the picture at path decoded by the server, a
// JPEG or a PNG Blob: of the version {mtime, size} says, if given; with
// thumbnail, the file's own thumbnail where it has one big enough.
export async function serverDecoded(path, { mtime, size, thumbnail = false, signal } = {}) {
    const t = await call({ type: "image-decode", path, if_mtime: mtime, if_size: size, thumbnail }, { signal });
    const abort = () => t.close();
    signal?.addEventListener("abort", abort, { once: true });
    try {
        return await collect(t, t.reply.length, () => {}, t.reply.type);
    } finally {
        signal?.removeEventListener("abort", abort);
        t.close();
    }
}

// saveBlob saves blob as a download named name. The link that does it goes
// in the open dialog, if there is one, since a modal dialog makes the rest
// of the page inert, which stops its links working.
export function saveBlob(blob, name) {
    const url = URL.createObjectURL(blob.type === "application/octet-stream" ? blob : blob.slice(0, blob.size, "application/octet-stream"));
    const a = Object.assign(document.createElement("a"), { href: url, download: name, hidden: true });
    const dialogs = document.querySelectorAll("dialog[open]");
    (dialogs[dialogs.length - 1] ?? document.body).append(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 60000);
}

files.tabtop/session-state.js:
import { store, storeJSON, storedJSON } from "./stored.js";

// Pages import this from <base>/tabtop/, so its parent identifies the
// deployment even when several instances share one origin.
export const SESSION_KEY = "tabtop_session:" + new URL("../", import.meta.url).pathname;

// The session from logging in: its id and secret, kept in this browser's
// storage and shared by the desktop, terminal and downloads.
export function storedSession() {
    const s = storedJSON(SESSION_KEY);
    return s?.id && s?.secret ? s : null;
}

// forgetSession forgets the stored session, or, given one that's over,
// forgets it only if it's still the one stored: not a newer login, from
// this page or another.
export function forgetSession(over) {
    if (!over || storedSession()?.id === over.id) {
        store(SESSION_KEY, null);
        forgetThumbnails();
    }
}

// THUMBNAIL_CACHE is where the files page keeps thumbnails of pictures
// (see thumbnails.js): this deployment's, gone with its session, as what
// they show is private.
export const THUMBNAIL_CACHE = "tabtop-thumbnails:" + new URL("../", import.meta.url).pathname;

function forgetThumbnails() {
    try {
        globalThis.caches?.delete(THUMBNAIL_CACHE).catch(() => {});
    } catch {
        // No Cache Storage here: nothing kept.
    }
}

// (Not remembered, if the browser won't: this page still has it.)
export const saveSession = (s) => storeJSON(SESSION_KEY, s);

files.tabtop/session.js:
import { loginForm } from "./login-ui.js";
import { storedSession } from "./session-state.js";
export { SESSION_KEY, storedSession, forgetSession, saveSession } from "./session-state.js";

// Only one login form at a time, however many tunnels are waiting for it.
let pendingLogin = null;

// session returns the stored session, or shows a login form over the page
// and returns the new one.
export async function session(title) {
    const s = storedSession();
    if (s) {
        return s;
    }
    pendingLogin ??= loginForm(title).finally(() => (pendingLogin = null));
    return pendingLogin;
}

// renewSession shows the login form, with a Cancel button, to log in
// again before the session runs out, and resolves to the new session, or
// null if it's cancelled. The old session goes on until it's ended: what
// it has open then reconnects with the new one.
export function renewSession(title) {
    return loginForm(title, true);
}

files.tabtop/stream-worker.js:
// Registration is shared by downloads and media, but their scopes and
// controller requirements differ. Browser APIs and clocks are injectable so
// lifecycle tests import this module without modifying its source.
export const STREAM_WORKER_VERSION = 8;
const scriptURL = new URL(`./download-sw.js?v=${STREAM_WORKER_VERSION}`, import.meta.url);

export function createWorkerRegistration({ scope, requireController = false, serviceWorker,
    now = () => Date.now(), delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms)), timeout = 5000 }) {
    let pending = null;
    return function getWorker() {
        pending ??= (async () => {
            try {
                const api = serviceWorker ?? globalThis.navigator?.serviceWorker;
                if (!api) return null;
                const reg = await api.register(scriptURL, { scope: typeof scope === "function" ? scope() : scope });
                const ready = () => reg.active && !reg.installing && !reg.waiting &&
                    (!requireController || api.controller === reg.active);
                const end = now() + timeout;
                while (!ready() && now() < end) await delay(50);
                return ready() ? reg.active : null;
            } catch {
                return null;
            }
        })();
        const attempt = pending;
        return attempt.then((worker) => {
            // A timed-out activation or temporary error can succeed next time.
            if (!worker && pending === attempt) pending = null;
            return worker;
        });
    };
}

export const streamWorker = createWorkerRegistration({ scope: new URL("./stream/", import.meta.url).pathname });
export const mediaWorker = createWorkerRegistration({ scope: () => new URL("./", location.href).pathname, requireController: true });

